pub fn enumerate_paths(root: &Value, pattern: &PathPattern) -> Vec<ConcretePath> {
    let mut out = Vec::new();
    let mut current = Vec::new();
    walk_enum(root, &pattern.segments, 0, &mut current, &mut out);
    out
}

fn walk_enum(node: &Value, segs: &[Segment], si: usize, cur: &mut Vec<PathElement>, out: &mut Vec<ConcretePath>) {
    if si >= segs.len() {
        out.push(ConcretePath(cur.clone()));
        return;
    }
    match &segs[si] {
        Segment::Descendant => {
            // zero-or-more levels: first try the remainder at this node (zero level)
            walk_enum(node, segs, si + 1, cur, out);
            // then descend one level and repeat the descendant segment
            if let Some(map) = node.as_object() {
                for (k, v) in map.iter() {
                    cur.push(PathElement::Key(k.to_string()));
                    walk_enum(v, segs, si, cur, out);
                    cur.pop();
                }
            } else if let Some(arr) = node.as_array() {
                for (idx, v) in arr.iter().enumerate() {
                    cur.push(PathElement::Index(idx));
                    walk_enum(v, segs, si, cur, out);
                    cur.pop();
                }
            }
        }
        Segment::Key(k) => {
            if let Some(map) = node.as_object() {
                if let Some(v) = map.get(k.as_str()) {
                    cur.push(PathElement::Key(k.clone()));
                    walk_enum(v, segs, si + 1, cur, out);
                    cur.pop();
                }
            }
        }
        Segment::Index(idx) => {
            if let Some(arr) = node.as_array() {
                if let Some(v) = arr.get(*idx) {
                    cur.push(PathElement::Index(*idx));
                    walk_enum(v, segs, si + 1, cur, out);
                    cur.pop();
                }
            }
        }
        Segment::Wildcard => {
            if let Some(map) = node.as_object() {
                for (k, v) in map.iter() {
                    cur.push(PathElement::Key(k.to_string()));
                    walk_enum(v, segs, si + 1, cur, out);
                    cur.pop();
                }
            } else if let Some(arr) = node.as_array() {
                for (idx, v) in arr.iter().enumerate() {
                    cur.push(PathElement::Index(idx));
                    walk_enum(v, segs, si + 1, cur, out);
                    cur.pop();
                }
            }
            // scalar: wildcard matches nothing
        }
    }
}
