pub fn parse_path(input: &str) -> Result<PathPattern, PathParseError> {
    let s = input.trim();
    if s.is_empty() { return Err(...); }
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i = 0;
    let mut segments = Vec::new();

    // optional leading root markers: '$' and/or leading dots
    if i < n && chars[i] == '$' { i += 1; }
    // We'll handle dots in the loop; but consume a single leading '.'
    if i < n && chars[i] == '.' { i += 1; }

    loop {
        if i >= n { break; }
        let c = chars[i];
        if c == '.' {
            // could be second dot of '..' or a stray separator
            i += 1;
            if i < n && chars[i] == '.' {
                // '..' descendant
                i += 1;
                segments.push(Segment::Descendant);
                // after '..' there may be a key directly (e.g. ..email)
            }
            continue;
        }
        if c == '[' {
            // parse bracket
            i += 1;
            while i < n && chars[i].is_whitespace() { i += 1; }
            if i >= n { return Err(unclosed); }
            if chars[i] == '"' || chars[i] == '\'' {
                let q = chars[i]; i += 1;
                let mut key = String::new();
                let mut closed = false;
                while i < n {
                    let ch = chars[i];
                    if ch == '\\' && i+1 < n {
                        let next = chars[i+1];
                        // map common escapes
                        match next { 'n'=>key.push('\n'), 't'=>..., '"'=>..., '\''=>..., '\\'=>key.push('\\'), '/'=>..., _=>key.push(next) }
                        i += 2; continue;
                    }
                    if ch == q { closed = true; i += 1; break; }
                    key.push(ch); i += 1;
                }
                if !closed { return Err(unclosed string); }
                while i<n && chars[i].is_whitespace() { i+=1; }
                if i>=n || chars[i] != ']' { return Err(expected ]); }
                i += 1;
                segments.push(Segment::Key(key));
            } else {
                let start = i;
                while i < n && chars[i] != ']' { i += 1; }
                if i >= n { return Err(unclosed bracket); }
                let raw: String = chars[start..i].iter().collect();
                let inner = raw.trim();
                if inner == "*" { segments.push(Segment::Wildcard); }
                else {
                    let idx: usize = inner.parse().map_err(|_| invalid index)?;
                    segments.push(Segment::Index(idx));
                }
                i += 1; // consume ']'
            }
            continue;
        }
        // bare token until '.' or '['
        let start = i;
        while i < n && chars[i] != '.' && chars[i] != '[' { i += 1; }
        let token: String = chars[start..i].iter().collect();
        let token = token.trim(); // whitespace? bare tokens shouldn't have spaces but trim safe
        if token.is_empty() { return Err(empty segment); }
        if token == "**" { segments.push(Segment::Descendant); }
        else if token == "*" { segments.push(Segment::Wildcard); }
        else { segments.push(Segment::Key(token.to_string())); }
    }

    if segments.is_empty() { return Err(empty path); }
    Ok(PathPattern { raw: s.to_string(), segments })
}
```

